//! What a managed endpoint is reached THROUGH: the address a client sends to, the
//! certificate that secures that address, and the network placement its gateway runs in.
//!
//! A managed endpoint is "a gateway that connects Amazon EMR Studio to Amazon EMR on EKS"
//! (`smithy_query(query="doc", operation="CreateManagedEndpoint")`), and the `Endpoint`
//! shape declares the members a client reads to actually reach that gateway:
//! `serverUrl` ("The server URL of the endpoint"), `certificateAuthority` ("The
//! certificate generated by emr control plane on customer behalf to secure the managed
//! endpoint"), `securityGroup` and `subnetIds`
//! (`smithy_query(query="shape", shape="Endpoint")`).
//!
//! All of it is settled when the endpoint is CREATED — the gateway's address, its
//! certificate and the network it is attached to are what the endpoint was provisioned
//! with — stored on the record as an [`EndpointConnection`] and reported unchanged by
//! every later read. So two reads of one endpoint never disagree, and no read mints
//! anything.
//!
//! Nothing here is a per-run value, and nothing here is another service's resource: the
//! address is built from this emulator's own base URL and the endpoint's own path, the
//! certificate is material this service GENERATED, and the placement is read off what the
//! service that owns it answered ([`super::container_cluster_network`]).
//!
//! A child module of [`super`] rather than more of that file: an endpoint's address and
//! its certificate are one concern.

use super::ContainerClusterNetwork;

/// How long the certificate generated for a managed endpoint is valid.
///
/// The certificate secures the endpoint's own address, and AWS Certificate Manager's
/// published validity for the certificates it issues is 13 months — 395 days — so the
/// material bears that window from the day the endpoint was created.
const CERTIFICATE_VALIDITY_DAYS: i64 = 395;

/// Milliseconds in a day, for the end of that window.
const MILLIS_PER_DAY: i64 = 24 * 60 * 60 * 1_000;

/// The connection metadata one managed endpoint was provisioned with.
///
/// Held on [`super::ManagedEndpointRecord`] and rendered into the modelled `Endpoint` by
/// [`super::ManagedEndpointRecord::to_endpoint`], so `DescribeManagedEndpoint` and
/// `ListManagedEndpoints` report one copy of it.
#[derive(Debug, Clone)]
pub struct EndpointConnection {
    /// `serverUrl` — the address a client sends to, which leads back to THIS emulator.
    pub server_url: String,
    /// `certificateAuthority$certificateData` — the base64-encoded PEM of the certificate
    /// generated for that address.
    pub certificate_data: String,
    /// `securityGroup` — the group the gateway runs in, as the service that owns the
    /// container cluster reported it, and `None` when it reported none.
    pub security_group: Option<String>,
    /// `subnetIds` — the subnets the gateway runs in, as that same answer listed them, and
    /// EMPTY when there was no answer: an endpoint reports a placement only where its
    /// owner has one.
    pub subnet_ids: Vec<String>,
}

/// The connection metadata for the endpoint `endpoint_id` of `virtual_cluster_id`.
///
/// `gateway` is the base URL this emulator is reachable at
/// (`smithy_server_runtime::OperationContext::endpoint`), `certificate_data` the material
/// [`mint_endpoint_certificate`] issued for that address, and `network` the placement
/// [`super::container_cluster_network`] read off the container cluster's owner. This
/// assembles those three; it resolves nothing of its own.
pub fn endpoint_connection(
    gateway: &str,
    virtual_cluster_id: &str,
    endpoint_id: &str,
    certificate_data: String,
    network: ContainerClusterNetwork,
) -> EndpointConnection {
    EndpointConnection {
        server_url: endpoint_server_url(gateway, virtual_cluster_id, endpoint_id),
        certificate_data,
        security_group: network.security_group,
        subnet_ids: network.subnet_ids,
    }
}

/// The address the endpoint is reached at: this emulator's own base URL followed by the
/// endpoint's path — `/virtualclusters/{virtualClusterId}/endpoints/{id}`, the path every
/// call about this endpoint is addressed to (`smithy_query(query="operation",
/// operation="DescribeManagedEndpoint")`).
///
/// Built from the base the emulator is reachable at rather than from a regional AWS host,
/// so the address this member reports leads back HERE, to the endpoint it names.
pub fn endpoint_server_url(gateway: &str, virtual_cluster_id: &str, endpoint_id: &str) -> String {
    let base = gateway.strip_suffix('/').unwrap_or(gateway);
    format!("{base}/virtualclusters/{virtual_cluster_id}/endpoints/{endpoint_id}")
}

/// The certificate that secures the endpoint reached at `gateway`, as
/// `Certificate$certificateData` carries it: "The base64 encoded PEM certificate data
/// generated for managed endpoint".
///
/// A REAL self-signed X.509 certificate, issued through the maintained generator this tree
/// already uses for certificate material, so what the member carries is a certificate a
/// client can parse and pin rather than text in the shape of one. It is issued FOR the
/// host the endpoint is reached at (its subject alternative name) and names the endpoint in
/// the subject's common name, and it is valid from the day the endpoint was created for
/// [`CERTIFICATE_VALIDITY_DAYS`].
///
/// The private half is generated here and dropped: the control plane keeps it, and no
/// member of this service reports it.
///
/// `Certificate$certificateArn` stays absent beside it: that member names the certificate
/// as an AWS Certificate Manager certificate, and no ACM record answers for material this
/// service generated itself, so there is nothing to name it by. The material is what the
/// client needs and what this service has.
///
/// `None` when the material does not issue — which the create reports to its caller rather
/// than storing an endpoint whose address nothing secures.
pub fn mint_endpoint_certificate(
    gateway: &str,
    endpoint_name: &str,
    created_at_millis: i64,
) -> Option<String> {
    let host = gateway_host(gateway)?;
    let (from_year, from_month, from_day) = utc_day(created_at_millis)?;
    let (to_year, to_month, to_day) =
        utc_day(created_at_millis.saturating_add(CERTIFICATE_VALIDITY_DAYS * MILLIS_PER_DAY))?;
    let key = ::rcgen::KeyPair::generate().ok()?;
    let mut params = ::rcgen::CertificateParams::new(vec![host]).ok()?;
    let mut subject = ::rcgen::DistinguishedName::new();
    subject.push(::rcgen::DnType::CommonName, endpoint_name);
    params.distinguished_name = subject;
    params.not_before = ::rcgen::date_time_ymd(from_year, from_month, from_day);
    params.not_after = ::rcgen::date_time_ymd(to_year, to_month, to_day);
    let pem = params.self_signed(&key).ok()?.pem();
    // The standard-alphabet codec the wire serializer itself uses, so what the member
    // carries is base64 as `Base64Encoded` (pattern `^([A-Za-z0-9+/]{4})*…`) spells it.
    Some(::aws_smithy_types::base64::encode(pem))
}

/// The HOST of the emulator's base URL — the name the gateway's certificate is issued for.
///
/// An IPv6 literal is unwrapped from its brackets, so the certificate carries the address
/// itself rather than the URL's spelling of it.
fn gateway_host(gateway: &str) -> Option<String> {
    let uri: ::http::Uri = gateway.parse().ok()?;
    let host = uri.host()?.trim_start_matches('[').trim_end_matches(']');
    (!host.is_empty()).then(|| host.to_string())
}

/// The UTC day `millis` falls on, as `(year, month, day)` — the form a certificate's
/// validity bound is stated in.
///
/// An X.509 validity period is read at whole-day resolution by the tools that inspect one,
/// so the window runs from the day the endpoint was created to the day its certificate
/// expires.
fn utc_day(millis: i64) -> Option<(i32, u8, u8)> {
    use ::chrono::Datelike;

    let day = ::chrono::DateTime::from_timestamp_millis(millis)?.date_naive();
    Some((
        day.year(),
        u8::try_from(day.month()).ok()?,
        u8::try_from(day.day()).ok()?,
    ))
}
